'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import dynamic from 'next/dynamic';
import { uploadFile } from '@/lib/api';
import { createPartner, updatePartner } from '@/lib/api/partners';

const WordLikeEditor = dynamic(() => import('@/components/editor/WordLikeEditor'), { ssr: false });

const STRAPI_URL = process.env.NEXT_PUBLIC_STRAPI_URL || 'http://localhost:1337';

interface PartnerData {
  documentId?: string;
  name: string;
  short_name?: string;
  logo?: { id: number; url: string } | null;
  description?: string;
  website?: string;
  contact_person?: string;
  contact_phone?: string;
  contact_email?: string;
  cooperation_type?: string;
  sort_order?: number;
  is_active?: boolean;
}

interface UploadedFile {
  id: number;
  url: string;
}

export default function PartnerForm({ initialData }: { initialData?: PartnerData }) {
  const router = useRouter();
  const isEdit = !!initialData?.documentId;

  const [form, setForm] = useState({
    name: initialData?.name || '',
    short_name: initialData?.short_name || '',
    description: initialData?.description || '',
    website: initialData?.website || '',
    contact_person: initialData?.contact_person || '',
    contact_phone: initialData?.contact_phone || '',
    contact_email: initialData?.contact_email || '',
    cooperation_type: initialData?.cooperation_type || '',
    sort_order: initialData?.sort_order ?? 0,
    is_active: initialData?.is_active ?? true,
    logoId: initialData?.logo?.id ? String(initialData.logo.id) : '',
    logoPreview: initialData?.logo?.url ? `${STRAPI_URL}${initialData.logo.url}` : '',
  });

  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [saving, setSaving] = useState(false);

  const handleEditorUpload = async (file: File): Promise<string> => {
    const uploaded = (await uploadFile(file)) as UploadedFile[];
    const url = uploaded?.[0]?.url || '';
    return url.startsWith('http') ? url : `${STRAPI_URL}${url}`;
  };

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLogoFile(file);
    setForm((p) => ({ ...p, logoPreview: URL.createObjectURL(file) }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.name.trim()) {
      alert('单位名称不能为空');
      return;
    }

    setSaving(true);
    try {
      let logoId = form.logoId;
      if (logoFile) {
        const uploaded = (await uploadFile(logoFile)) as UploadedFile[];
        if (uploaded?.[0]?.id) logoId = String(uploaded[0].id);
      }

      const payload = {
        name: form.name,
        short_name: form.short_name || null,
        description: form.description || null,
        website: form.website || null,
        contact_person: form.contact_person || null,
        contact_phone: form.contact_phone || null,
        contact_email: form.contact_email || null,
        cooperation_type: form.cooperation_type || null,
        sort_order: Number(form.sort_order) || 0,
        is_active: form.is_active,
        logo: logoId ? Number(logoId) : null,
      };

      if (isEdit) {
        await updatePartner(initialData!.documentId!, payload);
      } else {
        await createPartner(payload);
      }

      alert('保存成功！');
      router.push('/dashboard/partners');
      router.refresh();
    } catch (error) {
      console.error('保存失败:', error);
      alert('保存失败：' + (error instanceof Error ? error.message : '未知错误'));
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {/* 基本信息 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            单位名称 <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            value={form.name}
            onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))}
            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="请输入单位全称"
            required
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            单位简称
          </label>
          <input
            type="text"
            value={form.short_name}
            onChange={(e) => setForm((p) => ({ ...p, short_name: e.target.value }))}
            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="请输入单位简称"
          />
        </div>
      </div>

      {/* Logo 上传 */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">
          单位 Logo
        </label>
        {form.logoPreview && (
          <img
            src={form.logoPreview}
            alt="logo preview"
            className="w-32 h-20 object-contain border rounded mb-2 bg-gray-50"
          />
        )}
        <input
          type="file"
          accept="image/*"
          onChange={handleLogoChange}
          className="block text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded file:border-0 file:text-sm file:font-medium file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
        />
      </div>

      {/* 企业简介 - 富文本编辑器 */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          企业简介
        </label>
        <WordLikeEditor
          value={form.description}
          onChange={(html) => setForm((p) => ({ ...p, description: html }))}
          uploadImage={handleEditorUpload}
        />
      </div>

      {/* 联系信息 */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            联系人
          </label>
          <input
            type="text"
            value={form.contact_person}
            onChange={(e) => setForm((p) => ({ ...p, contact_person: e.target.value }))}
            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="联系人姓名"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            联系电话
          </label>
          <input
            type="text"
            value={form.contact_phone}
            onChange={(e) => setForm((p) => ({ ...p, contact_phone: e.target.value }))}
            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="联系电话"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            联系邮箱
          </label>
          <input
            type="email"
            value={form.contact_email}
            onChange={(e) => setForm((p) => ({ ...p, contact_email: e.target.value }))}
            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="联系邮箱"
          />
        </div>
      </div>

      {/* 其他信息 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            官网地址
          </label>
          <input
            type="url"
            value={form.website}
            onChange={(e) => setForm((p) => ({ ...p, website: e.target.value }))}
            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="https://example.com"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            合作类型
          </label>
          <input
            type="text"
            value={form.cooperation_type}
            onChange={(e) => setForm((p) => ({ ...p, cooperation_type: e.target.value }))}
            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="如：战略合作、技术合作等"
          />
        </div>
      </div>

      {/* 排序和状态 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            排序
          </label>
          <input
            type="number"
            value={form.sort_order}
            onChange={(e) => setForm((p) => ({ ...p, sort_order: Number(e.target.value) }))}
            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="数字越小越靠前"
          />
        </div>

        <div className="flex items-center pt-7">
          <input
            type="checkbox"
            id="is_active"
            checked={form.is_active}
            onChange={(e) => setForm((p) => ({ ...p, is_active: e.target.checked }))}
            className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
          />
          <label htmlFor="is_active" className="ml-2 text-sm text-gray-700">
            启用显示
          </label>
        </div>
      </div>

      {/* 操作按钮 */}
      <div className="flex justify-end gap-4 pt-4 border-t">
        <button
          type="button"
          onClick={() => router.push('/dashboard/partners')}
          className="px-6 py-3 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 transition-colors"
        >
          取消
        </button>
        <button
          type="submit"
          disabled={saving}
          className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50"
        >
          {saving ? '保存中...' : '保存'}
        </button>
      </div>
    </form>
  );
}
